import argparse
import json
import sys
from pathlib import Path

def main():
    parser = argparse.ArgumentParser(description='R_V Contraction Measure Tool')
    parser.add_argument('--input', required=True, help='Input JSON file path')
    parser.add_argument('--output', required=True, help='Output report file path')
    args = parser.parse_args()

    # Read input JSON
    try:
        with open(args.input, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading input file: {e}", file=sys.stderr)
        sys.exit(1)

    # Extract data
    model_name = data.get('model_name', 'Unknown')
    measurements = data.get('measurements', [])
    marker = data.get('marker', '')

    # Calculate statistics
    if measurements:
        mean_val = sum(measurements) / len(measurements)
        min_val = min(measurements)
        max_val = max(measurements)
    else:
        mean_val = min_val = max_val = 0

    # Generate report
    report = f"""R_V Contraction Measurement Report
====================================

Model: {model_name}
Marker: {marker}

Measurements Summary:
- Count: {len(measurements)}
- Mean: {mean_val:.4f}
- Min: {min_val:.4f}
- Max: {max_val:.4f}
- Values: {measurements}

Status: Analysis complete.
"""

    # Write output
    try:
        Path(args.output).parent.mkdir(parents=True, exist_ok=True)
        with open(args.output, 'w') as f:
            f.write(report)
    except Exception as e:
        print(f"Error writing output file: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Report generated successfully: {args.output}")

if __name__ == '__main__':
    main()
EOF
